// The measured results the landing page shows, copied from docs/PROOF.md (generated by `bun run eval` from recorded
// runs and the separate answer keys). Never typed in from memory: tests/landing-proof.test.ts fails if a row here
// no longer matches the table in PROOF.md, so a new proof run must update both.
export type ProofRow = {
  agent: "Threadpull (Hazel)" | "Fixed rules" | "Check everything";
  ring: string; innocents: string; other: number; review: string; acorns: number;
  crs: number; questions: number; runtime: string;
};
export type ProofSeed = {
  seed: number; label: string; note: string; run: string; commit: string;
  /** acorns Hazel had spent when every ring member was marked Investigate */
  ringCompleteAt: number;
  rows: ProofRow[];
};

export const PROOF_URL = "https://github.com/Navibytes/Threadpull/blob/main/docs/PROOF.md";

