/** The row as PROOF.md prints it, for the test that keeps the two in step. */
export const markdownRow = (r: ProofRow) =>
  `| ${r.agent} | ${r.ring} | ${r.innocents} | ${r.other} | ${r.review} | ${r.acorns} | ${r.crs} | ${r.questions} | ${r.runtime} |`;
